create or replace function public.ffh_inbox_read_guard() returns trigger language plpgsql set search_path='' as $$begin if auth.role()<>'service_role' then if new.id is distinct from old.id or new.job_id is distinct from old.job_id or new.staff_id is distinct from old.staff_id or new.title is distinct from old.title or new.body is distinct from old.body or new.type is distinct from old.type or new.target_page is distinct from old.target_page or new.created_at is distinct from old.created_at then raise exception 'Only read_at can change';end if;if old.read_at is not null or new.read_at is null or new.read_at>now()+interval '1 minute' then raise exception 'Invalid read receipt';end if;end if;return new;end$$;
revoke execute on function public.rls_auto_enable() from public,anon,authenticated;
